  sort:{title:"Thinkers and arguments",groups:[{name:"Hobbes",items:["Strong sovereign authority","Order against destructive conflict"]},{name:"Locke",items:["Government by consent","Protection of natural rights"]},{name:"Montesquieu",items:["Distributed political functions","Checks on concentrated power"]}]},
  mapwork:{title:"Industry and ideas timeline",caption:"Place the events and developments on a timeline, explaining why industrial growth and abolition are not the same event.",items:[{p:"Seventeenth century",f:"Hobbes and Locke develop contrasting arguments about government"},{p:"Eighteenth century",f:"Enlightenment debate expands"},{p:"Later eighteenth century",f:"British industrialization accelerates"},{p:"1807",f:"Britain prohibits its slave trade"},{p:"1865",f:"Slavery abolished constitutionally in the United States"}]},
  casestudy:{title:"The mill and the plantation",text:"A fictional class studies a cotton mill's rising output and an account of plantation labour producing its raw cotton. One pupil argues that the mill's machinery proves enslaved labour was no longer economically important.",questions:[{q:"What connection has the pupil overlooked?",a:"The factory could depend on raw cotton produced by enslaved workers."},{q:"What does rising output show, and not show?",a:"It can show increased production, not the freedom or well-being of every worker in the supply chain."},{q:"What evidence is needed to explain abolition?",a:"Evidence of resistance, campaigns, political decisions, laws and economic changes."}]},
  apply:[{q:"How would you assess a new machine from both an owner's and a worker's perspective?",a:"Compare output and costs with wages, safety, working hours and effects on skills and employment."},{q:"Why can a theory of rights inspire criticism of the society that produced it?",a:"People excluded from those rights can use the stated principles to challenge unequal treatment."}],
